import json

def law_crimes_search(crime, location, year):
    return {
        "type": "function",
        "function": {
            "name": "law_crimes.search",
            "parameters": {
                "type": "object",
                "properties": {
                    "crime": crime,
                    "location": location,
                    "year": year
                },
                "required": [
                    "crime",
                    "location",
                    "year"
                ],
                "additionalProperties": False
            }
        }
    }

result = law_crimes_search("money laundering", "San Francisco", 2019)
result = law_crimes_search("money laundering", "Texas", 2018)

if result:
    print(json.dumps(result, indent=2))
else:
    print("NO_CALL")

