import json

def public_library_find_nearby(location, facilities):
    return {
        "name": "public_library.find_nearby",
        "parameters": {
            "type": "function",
            "function": {
                "name": "public_library.find_nearby",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "location": {
                            "type": "string",
                            "description": "The city and state, e.g. Boston, MA"
                        },
                        "facilities": {
                            "type": "array",
                            "items": {
                                "type": "string",
                                "enum": [
                                    "Wi-Fi",
                                    "Reading Room",
                                    "Fiction",
                                    "Children Section",
                                    "Cafe"
                                ]
                            },
                            "description": "Facilities and sections in public library."
                        }
                    },
                    "required": [
                        "location",
                        "facilities"
                    ],
                    "additionalProperties": false
                }
            }
        }
    }

print(json.dumps(public_library_find_nearby("New York, NY", ["Reading Room", "Fiction"]), indent=4))
print(json.dumps(public_library_find_nearby("Los Angeles, CA", ["Wi-Fi", "Children Section"]), indent=4))
print(json.dumps(public_library_find_nearby("Chicago, IL", ["Cafe", "Reading Room"]), indent=4))

